package kr.blackwiki.smp;
import org.bukkit.*;
import org.bukkit.block.data.BlockData;
import org.bukkit.command.CommandSender;
import org.bukkit.configuration.file.YamlConfiguration;
import org.bukkit.entity.Player;
import org.bukkit.scheduler.BukkitTask;
import java.nio.file.*;
import java.util.*;
/** Build once in unused sky space, checkpoint and resume without clearing existing terrain. */
final class SpawnDesignService {
    private final BlackWikiSMP p;private final Path file;private String stage="NONE",problem="";private int x,y,z,index,loading;private boolean cancelled;private BukkitTask task;private final Deque<int[]> chunks=new ArrayDeque<>();private final Set<Chunk> tickets=new HashSet<>();private List<SpawnPlan.Voxel> plan=List.of();private final Map<String,BlockData> data=new HashMap<>();
    SpawnDesignService(BlackWikiSMP p)throws Exception{this.p=p;file=p.getDataFolder().toPath().resolve("spawn-build.yml");if(Files.exists(file)){YamlConfiguration v=new YamlConfiguration();v.load(file.toFile());if(v.getInt("schema")!=1||v.getInt("template")!=SpawnPlan.VERSION)throw new IllegalArgumentException("Unknown spawn design journal");if(!p.spawnWorld.getUID().toString().equals(v.getString("world-id")))throw new IllegalArgumentException("Spawn journal belongs to a different world; retain original world/data together");stage=v.getString("stage","NONE");if(!Set.of("NONE","BUILDING","DONE").contains(stage))throw new IllegalArgumentException("Invalid spawn design stage");x=v.getInt("x");y=v.getInt("y");z=v.getInt("z");if(!stage.equals("NONE")&&(y<p.spawnWorld.getMinHeight()+3||y>p.spawnWorld.getMaxHeight()-14||Rules.outside(x-50,z-50,p.cfg().getDouble("border.center-x"),p.cfg().getDouble("border.center-z"),40000)||Rules.outside(x+49,z+49,p.cfg().getDouble("border.center-x"),p.cfg().getDouble("border.center-z"),40000)))throw new IllegalArgumentException("Invalid spawn design bounds");}}
    boolean busy(){return task!=null||loading>0||!chunks.isEmpty();}
    boolean done(){return stage.equals("DONE");}
    String status(){return !problem.isEmpty()?"생성 대기: "+problem:done()?"100×100 정원 스폰 · 생성 완료":busy()?"100×100 스폰 생성 "+(plan.isEmpty()?"청크 준비":index+"/"+plan.size()):stage.equals("BUILDING")?"중단 기록 있음 · 이어서 생성 가능":"아직 생성하지 않음";}
    void auto(){if(stage.equals("BUILDING")||p.cfg().getBoolean("spawn-design.auto-create",true)&&!done())start(Bukkit.getConsoleSender());}
    void start(CommandSender actor){if(!BanService.operator(actor)){p.tell(actor,"OP만 사용할 수 있습니다.");return;}if(busy()||done()){p.tell(actor,status());return;}if(p.backups.running()||p.resets.busy()){p.tell(actor,"백업·야생 초기화 완료 후 시작하세요.");return;}problem="";cancelled=false;if(stage.equals("NONE")){x=p.spawn().getBlockX();z=p.spawn().getBlockZ();}if(p.outside(new Location(p.spawnWorld,x-50,0,z-50))||p.outside(new Location(p.spawnWorld,x+49,0,z+49))){problem="경계 안쪽에 스폰 중심을 설정하세요.";return;}for(int cx=(x-50)>>4;cx<=(x+49)>>4;cx++)for(int cz=(z-50)>>4;cz<=(z+49)>>4;cz++)chunks.add(new int[]{cx,cz});p.tell(actor,"기존 지형 위에 100×100 정원 스폰을 준비합니다. /스폰꾸미기 상태");load();}
    private void load(){if(cancelled)return;while(loading<2&&!chunks.isEmpty()){int[] at=chunks.removeFirst();loading++;p.spawnWorld.getChunkAtAsync(at[0],at[1],true).whenComplete((chunk,error)->p.sync(()->{loading--;if(cancelled)return;if(error!=null){fail(error);return;}chunk.addPluginChunkTicket(p);tickets.add(chunk);if(chunks.isEmpty()&&loading==0)prepare();else load();}));}}
    private void prepare(){try{if(stage.equals("NONE")){int highest=p.spawnWorld.getMinHeight();for(int dx=-50;dx<50;dx++)for(int dz=-50;dz<50;dz++)highest=Math.max(highest,p.spawnWorld.getHighestBlockYAt(x+dx,z+dz,HeightMap.WORLD_SURFACE));y=Math.max(80,highest+8);if(y>p.spawnWorld.getMaxHeight()-14)throw new IllegalStateException("스폰 위에 빈 높이가 부족합니다. 낮은 지형에 스폰 중심을 설정하세요.");stage="BUILDING";save();}plan=SpawnPlan.build();index=0;task=Bukkit.getScheduler().runTaskTimer(p,this::step,1,1);}catch(Exception ex){fail(ex);}}
    private void step(){try{int budget=p.cfg().getInt("spawn-design.blocks-per-tick",1200);for(int i=0;i<budget&&index<plan.size();i++,index++){var v=plan.get(index);var block=p.spawnWorld.getBlockAt(x+v.x(),y+v.y(),z+v.z());if(block.getType()==v.type())continue;if(!block.getType().isAir())throw new IllegalStateException("다른 블록 발견: "+block.getX()+", "+block.getY()+", "+block.getZ()+". 기존 블록은 보존했습니다.");String key=v.data()==null?v.type().getKey().toString():v.data();block.setBlockData(data.computeIfAbsent(key,Bukkit::createBlockData),false);}if(index>=plan.size())finish();}catch(Exception ex){fail(ex);}}
    private void finish()throws Exception{task.cancel();task=null;Location before=p.spawn();Location destination=new Location(p.spawnWorld,x+.5,y+1,z+12.5,180,0);p.applySpawn(destination);p.npcs.spawnMenu(new Location(p.spawnWorld,x+.5,y+1,z+.5,0,0));p.spawnWorld.save(true);stage="DONE";try{save();}catch(Exception ex){stage="BUILDING";throw ex;}release();for(Player a:Bukkit.getOnlinePlayers())if(!a.isDead()&&!p.queue.waiting(a)&&!p.travel.inCombat(a)&&a.getWorld()==before.getWorld()&&Math.abs(a.getX()-before.getX())<=p.cfg().getInt("spawn.radius",500)&&Math.abs(a.getZ()-before.getZ())<=p.cfg().getInt("spawn.radius",500))a.teleportAsync(destination);p.getLogger().info("100x100 garden spawn completed; existing terrain preserved");}
    private void save()throws Exception{YamlConfiguration v=new YamlConfiguration();v.set("schema",1);v.set("template",SpawnPlan.VERSION);v.set("world-id",p.spawnWorld.getUID().toString());v.set("stage",stage);v.set("x",x);v.set("y",y);v.set("z",z);DataStore.atomic(file,v.saveToString());}
    private void release(){for(Chunk chunk:tickets)chunk.removePluginChunkTicket(p);tickets.clear();chunks.clear();}
    private void fail(Throwable ex){problem=ex.getMessage()==null?ex.getClass().getSimpleName():ex.getMessage();cancelled=true;if(task!=null){task.cancel();task=null;}chunks.clear();release();p.getLogger().log(java.util.logging.Level.WARNING,"Spawn build paused; existing blocks retained",ex);}
    void menu(Player a){if(!BanService.operator(a))return;Gui.Menu m=p.gui.make(a,"100×100 정원 스폰");m.inventory.setItem(13,Gui.item(Material.CHERRY_SAPLING,status(),"현재 스폰 위 빈 공간 · 기존 건축 보존","중앙 정자·메뉴 NPC·나무 12그루·분수 4개","조명·화단·산책로·벤치·외곽 울타리"));if(!done())p.gui.button(m,20,Material.GRASS_BLOCK,busy()?"생성 진행 중":"생성·이어짓기",b->{start(b);menu(b);});p.gui.button(m,24,Material.COMPASS,"스폰으로 이동",b->{b.closeInventory();p.travel.go(b,p.spawn());});p.gui.button(m,40,Material.CLOCK,"새로고침",this::menu);p.gui.show(a,m);}
    void command(CommandSender a,String[] args){if(!BanService.operator(a)){p.tell(a,"OP만 사용할 수 있습니다.");return;}if(args.length>0&&Set.of("생성","시작","start").contains(args[0]))start(a);else if(args.length>0||!(a instanceof Player))p.tell(a,status());else menu((Player)a);}
    void close(){cancelled=true;if(task!=null){task.cancel();task=null;}release();}
}
